capabilities.goldenSnippetJson:
{
  "state": {
    "selectedDate": "",
    "draft": ""
  },
  "collections": {
    "events": {
      "maxItems": 200
    }
  },
  "sources": [
    {
      "type": "calendar",
      "intervalMs": 60000
    }
  ],
  "root": "calendar_layout",
  "elements": {
    "calendar_layout": {
      "type": "Stack",
      "spacing": 8,
      "children": [
        "month_grid",
        "event_list"
      ]
    },
    "month_grid": {
      "type": "CalendarGrid",
      "bind": "state.selectedDate",
      "collection": "events",
      "dateField": "date"
    },
    "event_list": {
      "type": "List",
      "items": "events",
      "filter": "${state.selectedDate == '' || $item.date == state.selectedDate}",
      "emptyState": {
        "icon": "calendar",
        "title": "当日暂无日程",
        "subtitle": "点击上方日期可切换查看"
      },
      "itemTemplate": "event_row"
    },
    "event_row": {
      "type": "Text",
      "text": "• ${$item.title} (${$item.date})"
    }
  }
}

{
  "state": {
    "targetFormat": "png"
  },
  "collections": {
    "history": {
      "maxItems": 30
    }
  },
  "root": "image_drop_zone",
  "elements": {
    "image_drop_zone": {
      "type": "DropZone",
      "icon": "gallery",
      "title": "拖入图片或点击选择文件",
      "subtitle": "本地转换为目标格式，源文件保持不变",
      "onDrop": [
        {
          "type": "file.transform",
          "path": "${$drop.path}",
          "format": "${state.targetFormat}",
          "then": [
            {
              "type": "collection.prepend",
              "collection": "history",
              "item": {
                "name": "${$transform.outputName}",
                "path": "${$transform.outputPath}",
                "size": "${$transform.sizeText}"
              }
            }
          ]
        }
      ]
    }
  }
}

{
  "sources": [
    {
      "type": "deviceState",
      "intervalMs": 3000
    }
  ],
  "root": "audio_display_card",
  "elements": {
    "audio_display_card": {
      "type": "Card",
      "tone": "subtle",
      "children": [
        "volume_slider",
        "brightness_slider",
        "audio_output_row"
      ]
    },
    "volume_slider": {
      "type": "Slider",
      "title": "系统音量",
      "value": "${$device.volume}",
      "min": 0,
      "max": 100,
      "step": 2,
      "unit": "%",
      "onChange": {
        "type": "system.control",
        "targetId": "volume.set",
        "value": "${$value}"
      }
    },
    "brightness_slider": {
      "type": "Slider",
      "title": "屏幕亮度",
      "value": "${$device.brightness}",
      "min": 0,
      "max": 100,
      "step": 5,
      "unit": "%",
      "onChange": {
        "type": "system.control",
        "targetId": "brightness.set",
        "value": "${$value}"
      }
    },
    "audio_output_row": {
      "type": "KeyValueRow",
      "label": "音频输出",
      "value": "${$device.audioDeviceName}"
    }
  }
}

{
  "state": {
    "input": "",
    "output": ""
  },
  "sources": [
    {
      "type": "clipboard",
      "intervalMs": 2000
    }
  ],
  "root": "clipboard_root",
  "elements": {
    "clipboard_root": {
      "type": "Stack",
      "spacing": 8,
      "children": [
        "clipboard_card",
        "raw_input",
        "transform_actions_grid",
        "output_text"
      ]
    },
    "clipboard_card": {
      "type": "Card",
      "tone": "subtle",
      "children": [
        "clipboard_summary_row",
        "clipboard_preview_text"
      ]
    },
    "clipboard_summary_row": {
      "type": "KeyValueRow",
      "label": "当前剪贴板 (${$clipboard.kindLabel})",
      "value": "${$clipboard.length} 字符"
    },
    "clipboard_preview_text": {
      "type": "Text",
      "text": "${$clipboard.preview}",
      "style": "caption",
      "color": "secondary",
      "maxLines": 2
    },
    "raw_input": {
      "type": "TextArea",
      "bind": "state.input",
      "placeholder": "输入待处理文本（留空则直接处理剪贴板内容）…"
    },
    "transform_actions_grid": {
      "type": "Grid",
      "columns": "*,*,*",
      "spacing": 6,
      "children": [
        "json_pretty_btn",
        "base64_encode_btn",
        "timestamp_btn"
      ]
    },
    "json_pretty_btn": {
      "type": "Button",
      "text": "JSON 格式化",
      "onClick": {
        "type": "text.transform",
        "format": "jsonPretty",
        "text": "${state.input != '' ? state.input : $clipboard.text}",
        "key": "output",
        "mode": "copy"
      }
    },
    "base64_encode_btn": {
      "type": "Button",
      "text": "Base64 编码",
      "onClick": {
        "type": "text.transform",
        "format": "base64Encode",
        "text": "${state.input != '' ? state.input : $clipboard.text}",
        "key": "output",
        "mode": "copy"
      }
    },
    "timestamp_btn": {
      "type": "Button",
      "text": "时间戳转换",
      "onClick": {
        "type": "text.transform",
        "format": "timestampToDate",
        "text": "${state.input != '' ? state.input : $clipboard.text}",
        "key": "output",
        "mode": "copy"
      }
    },
    "output_text": {
      "type": "Text",
      "text": "${state.output}",
      "style": "mono",
      "maxLines": 6,
      "when": "${state.output != ''}"
    }
  }
}

{
  "root": "launcher_grid",
  "elements": {
    "launcher_grid": {
      "type": "Grid",
      "columns": "*,*",
      "spacing": 8,
      "children": [
        "downloads_btn",
        "documents_btn",
        "screenshot_btn",
        "calculator_btn"
      ]
    },
    "downloads_btn": {
      "type": "Button",
      "text": "下载目录",
      "icon": "download",
      "onClick": {
        "type": "launcher.open",
        "targetId": "downloads"
      }
    },
    "documents_btn": {
      "type": "Button",
      "text": "文档目录",
      "icon": "file",
      "onClick": {
        "type": "launcher.open",
        "targetId": "documents"
      }
    },
    "screenshot_btn": {
      "type": "Button",
      "text": "屏幕截图",
      "icon": "camera",
      "onClick": {
        "type": "launcher.open",
        "targetId": "ms-screenclip:"
      }
    },
    "calculator_btn": {
      "type": "Button",
      "text": "计算器",
      "icon": "calculator",
      "onClick": {
        "type": "launcher.open",
        "targetId": "ms-calculator:"
      }
    }
  }
}

{
  "state": {
    "format": "png"
  },
  "collections": {
    "outputs": {
      "maxItems": 30
    }
  },
  "root": "converter_root",
  "elements": {
    "converter_root": {
      "type": "Stack",
      "spacing": 8,
      "children": [
        "format_selector",
        "image_drop_zone",
        "outputs_list"
      ]
    },
    "format_selector": {
      "type": "Segmented",
      "bind": "state.format",
      "options": [
        {
          "value": "png",
          "label": "PNG"
        },
        {
          "value": "jpg",
          "label": "JPG"
        },
        {
          "value": "bmp",
          "label": "BMP"
        },
        {
          "value": "ico",
          "label": "ICO"
        }
      ]
    },
    "image_drop_zone": {
      "type": "DropZone",
      "icon": "gallery",
      "title": "拖入图片或点击选择",
      "subtitle": "自动转为 ${state.format} 并保存在原目录",
      "onDrop": [
        {
          "type": "file.transform",
          "path": "${$drop.path}",
          "format": "${state.format}",
          "then": [
            {
              "type": "collection.prepend",
              "collection": "outputs",
              "item": {
                "name": "${$transform.outputName}",
                "path": "${$transform.outputPath}"
              }
            }
          ]
        }
      ]
    },
    "outputs_list": {
      "type": "List",
      "items": "outputs",
      "itemTemplate": "output_chip"
    },
    "output_chip": {
      "type": "FileChip",
      "fileName": "${$item.name}",
      "filePath": "${$item.path}"
    }
  }
}

{
  "state": {
    "draft": ""
  },
  "collections": {
    "tasks": {
      "maxItems": 100
    }
  },
  "root": "extract_tasks_btn",
  "elements": {
    "extract_tasks_btn": {
      "type": "Button",
      "text": "拆解待办事项",
      "icon": "sparkles",
      "variant": "accent",
      "onClick": {
        "type": "ai.run",
        "guard": "${state.draft != ''}",
        "prompt": "将以下内容拆解为可执行待办事项(items: title)：\n${state.draft}",
        "collection": "tasks",
        "itemsPath": "items",
        "fieldMap": {
          "title": "title"
        },
        "then": [
          {
            "type": "state.set",
            "key": "draft",
            "value": ""
          }
        ]
      }
    }
  }
}

{
  "root": "test_reminder_btn",
  "elements": {
    "test_reminder_btn": {
      "type": "Button",
      "text": "发送测试提醒",
      "icon": "bell",
      "onClick": {
        "type": "reminder.notify",
        "text": "定时提醒",
        "message": "预设提醒时间已到。"
      }
    }
  }
}

{
  "state": {
    "todayCount": 1200
  },
  "settings": [
    {
      "key": "modules",
      "type": "moduleList",
      "label": "显示模块与排序",
      "default": "overview:1,chart:1",
      "options": [
        {
          "value": "overview",
          "label": "今日概览"
        },
        {
          "value": "chart",
          "label": "趋势卡片"
        }
      ]
    },
    {
      "key": "dailyGoal",
      "type": "number",
      "label": "每日目标",
      "default": 2000
    },
    {
      "key": "compactMode",
      "type": "toggle",
      "label": "紧凑模式",
      "default": false
    }
  ],
  "root": "settings_root",
  "elements": {
    "settings_root": {
      "type": "Stack",
      "padding": "12,10,12,12",
      "children": [
        "modules_stack"
      ]
    },
    "modules_stack": {
      "type": "ModuleStack",
      "bind": "settings.modules",
      "spacing": 8,
      "children": [
        "overview",
        "chart"
      ]
    },
    "overview": {
      "type": "StatCard",
      "title": "今日累计",
      "value": "${state.todayCount}",
      "progress": "${state.todayCount * 100 / $settings.dailyGoal}"
    },
    "chart": {
      "type": "Card",
      "tone": "subtle",
      "when": "${$settings.compactMode != true}",
      "children": [
        "chart_caption"
      ]
    },
    "chart_caption": {
      "type": "Text",
      "text": "趋势详情",
      "style": "caption",
      "color": "secondary"
    }
  }
}

{
  "state": {
    "notes": "### Quick Notes\n- [x] Ship native widgets\n- [ ] Review metrics"
  },
  "popovers": {
    "editNotes": {
      "width": 300,
      "height": 220,
      "placement": "bottom",
      "root": "edit_notes_body"
    }
  },
  "root": "notes_root",
  "elements": {
    "notes_root": {
      "type": "Stack",
      "padding": "12,10,12,12",
      "spacing": 8,
      "children": [
        "edit_notes_btn",
        "notes_markdown"
      ]
    },
    "edit_notes_btn": {
      "type": "Button",
      "text": "Edit Markdown",
      "icon": "edit",
      "popover": "editNotes"
    },
    "notes_markdown": {
      "type": "Markdown",
      "bind": "state.notes"
    },
    "edit_notes_body": {
      "type": "Stack",
      "padding": "12",
      "spacing": 8,
      "children": [
        "notes_editor",
        "close_editor_btn"
      ]
    },
    "notes_editor": {
      "type": "TextArea",
      "bind": "state.notes",
      "minHeight": 130
    },
    "close_editor_btn": {
      "type": "Button",
      "text": "Done",
      "variant": "accent",
      "onClick": {
        "type": "popover.close",
        "popoverId": "editNotes"
      }
    }
  }
}

{
  "state": {
    "noteContent": "# Scratchpad"
  },
  "settings": [
    {
      "key": "notePath",
      "type": "text",
      "label": "Markdown File Path",
      "default": "%USERPROFILE%\\Documents\\deskbox-note.md"
    }
  ],
  "sources": [
    {
      "id": "localNote",
      "type": "fileText",
      "path": "${$settings.notePath}",
      "stateKey": "noteContent",
      "intervalMs": 5000
    }
  ],
  "root": "note_sync_root",
  "elements": {
    "note_sync_root": {
      "type": "Stack",
      "padding": "12,10,12,12",
      "spacing": 8,
      "children": [
        "note_editor",
        "save_note_btn"
      ]
    },
    "note_editor": {
      "type": "TextArea",
      "bind": "state.noteContent",
      "minHeight": 100
    },
    "save_note_btn": {
      "type": "Button",
      "text": "Save to File",
      "variant": "accent",
      "onClick": {
        "type": "file.writeText",
        "path": "${$settings.notePath}",
        "text": "${state.noteContent}",
        "append": false
      }
    }
  }
}
